<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { api, type IndiaGsecHistory, type SovereignTenor } from '../services/api'

const props = defineProps<{ market: string; description: string; historyPath: string; id: string; latestLabel: string; changeLabel: string; tenors: SovereignTenor[]; flagSrc: string }>()
const tenor = ref<SovereignTenor>(props.tenors.includes('10Y') ? '10Y' : props.tenors[0])
const history = ref<IndiaGsecHistory | null>(null)
const loading = ref(true)
const error = ref('')
const activeIndex = ref<number | null>(null)
const tooltip = ref({ x: 0, y: 0 })
const labels: Record<SovereignTenor, string> = { '1Y': '1 Year', '2Y': '2 Years', '5Y': '5 Years', '10Y': '10 Years' }

async function load() { loading.value = true; error.value = ''; activeIndex.value = null; try { history.value = (await api.get<IndiaGsecHistory>(props.historyPath, { params: { tenor: tenor.value } })).data } catch (e: any) { history.value = null; error.value = e?.response?.data?.detail || e?.message || `Unable to load ${props.market} government bond yield data.` } finally { loading.value = false } }
onMounted(load)
watch(tenor, load)

const latest = computed(() => { const points = history.value?.points ?? []; return points.length ? points[points.length - 1] : null })
const change = computed(() => { const points = history.value?.points ?? []; return points.length > 1 ? points[points.length - 1].yield_percent - points[0].yield_percent : null })
const chart = computed(() => { const points = history.value?.points ?? []; if (points.length < 2) return { line: '', area: '', min: 0, max: 0 }; const values = points.map((point) => point.yield_percent), padding = Math.max((Math.max(...values) - Math.min(...values)) * .18, .04), min = Math.min(...values) - padding, max = Math.max(...values) + padding, coordinates = points.map((point, index) => `${((index / (points.length - 1)) * 100).toFixed(2)},${(92 - ((point.yield_percent - min) / (max - min)) * 80).toFixed(2)}`); return { line: coordinates.join(' '), area: `0,100 ${coordinates.join(' ')} 100,100`, min, max } })
const activePoint = computed(() => { const points = history.value?.points ?? [], index = activeIndex.value; if (index === null || points.length < 2 || !points[index]) return null; const point = points[index]; return { point, x: (index / (points.length - 1)) * 100, y: 92 - ((point.yield_percent - chart.value.min) / (chart.value.max - chart.value.min)) * 80 } })
function selectPoint(event: PointerEvent) { const points = history.value?.points ?? [], svg = event.currentTarget as SVGSVGElement; if (points.length < 2) return; const rect = svg.getBoundingClientRect(); activeIndex.value = Math.round(Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width)) * (points.length - 1)); tooltip.value = { x: event.clientX - rect.left + 52, y: event.clientY - rect.top } }
const date = (value: string) => new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(`${value}T00:00:00`))
</script>

<template><section :id="id" class="market-section"><section class="hero"><p class="eyebrow"><img class="market-flag" :src="flagSrc" alt="" aria-hidden="true">{{ market.toUpperCase() }} · GOVERNMENT SECURITIES</p><div class="headline-row"><div><h1>{{ labels[tenor] }} {{ market }} Government Bond Yield</h1><p class="subhead">{{ description }}</p></div><label class="tenor-select"><span>Bond maturity</span><select v-model="tenor" :aria-label="`Select ${market} government bond maturity`"><option v-for="availableTenor in tenors" :key="availableTenor" :value="availableTenor">{{ labels[availableTenor] }}</option></select></label></div></section><section class="chart-card" aria-live="polite"><div v-if="loading" class="state">Loading the latest yield history…</div><div v-else-if="error" class="state error"><strong>Yield history unavailable.</strong><br>{{ error }}</div><template v-else-if="history && latest"><div class="chart-heading"><div><p class="metric-label">{{ latestLabel }}</p><p class="yield-value">{{ latest.yield_percent.toFixed(2) }}<small>%</small></p></div><div class="latest-date"><span>AS OF</span>{{ date(latest.date) }}</div></div><div class="chart-wrap"><div class="gridline top"><span>{{ chart.max.toFixed(2) }}%</span></div><div class="gridline mid"><span>{{ ((chart.max + chart.min) / 2).toFixed(2) }}%</span></div><div class="gridline bottom"><span>{{ chart.min.toFixed(2) }}%</span></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" :aria-label="`${labels[tenor]} ${market} government bond yield chart`" @pointermove="selectPoint" @pointerleave="activeIndex = null"><defs><linearGradient :id="`fill-${id}`" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#e5792e" stop-opacity=".28"/><stop offset="1" stop-color="#e5792e" stop-opacity="0"/></linearGradient></defs><polygon :points="chart.area" :fill="`url(#fill-${id})`"/><polyline :points="chart.line" fill="none" stroke="#ef7b32" stroke-width="1.1" vector-effect="non-scaling-stroke"/><line v-if="activePoint" :x1="activePoint.x" :x2="activePoint.x" y1="0" y2="100" class="chart-guide"/><circle v-if="activePoint" :cx="activePoint.x" :cy="activePoint.y" r="2.3" class="chart-marker" vector-effect="non-scaling-stroke"/></svg><div v-if="activePoint" class="chart-tooltip" :style="{ left: `${tooltip.x}px`, top: `${tooltip.y}px` }" role="status"><strong>{{ date(activePoint.point.date) }}</strong><span>{{ activePoint.point.yield_percent.toFixed(2) }}%</span></div></div><div class="axis"><span>{{ date(history.points[0].date) }}</span><span>{{ date(latest.date) }}</span></div><div v-if="change !== null" class="period-change" :class="{ positive: change >= 0 }"><span>{{ changeLabel }}</span>{{ change >= 0 ? '+' : '' }}{{ change.toFixed(2) }} pp</div></template><div v-else class="state">No yield observations are available for this maturity.</div></section><p v-if="history" class="source">Source: {{ history.source }} · {{ history.data_status }}</p></section></template>
